import ast,hashlib,json
from pathlib import Path
r=json.load(open('/tmp/r001-runtime.json')); p=json.load(open('/workspace/proposal.json'))
def validate(value,schema,path='"'$'"'):
 ty=schema.get('type')
 if ty=='object':
  assert isinstance(value,dict),(path,'not object')
  assert not(set(schema.get('required',[]))-set(value)),(path,'missing required')
  if schema.get('additionalProperties') is False: assert not(set(value)-set(schema.get('properties',{}))),(path,'extra properties')
  for k,x in value.items():
   if k in schema.get('properties',{}):validate(x,schema['properties'][k],path+'.'+k)
 elif ty=='array':
  assert isinstance(value,list),(path,'not array')
  assert len(value)>=schema.get('minItems',0),(path,'too short')
  for i,x in enumerate(value):validate(x,schema.get('items',{}),path+'['+str(i)+']')
 elif ty=='string':assert isinstance(value,str) and len(value)>=schema.get('minLength',0),(path,'not string/too short')
 elif ty=='boolean':assert isinstance(value,bool),(path,'not bool')
 if 'const' in schema: assert value==schema['const'],(path,'const mismatch')
 if 'enum' in schema:assert value in schema['enum'],(path,'enum mismatch')
validate(p['study'],r['study_schema'])
assert p['study']['protocol_ref']==r['required_study_protocol_ref']
assert p['study']['evidence_refs']==r['context']['allowed_observation_ids']
assert p['parent_trial'] in r['context']['allowed_observation_ids']
assert 1<=len(p['variants'])<=4 and any(v['role']=='candidate' for v in p['variants'])
for v in p['variants']:
 assert set(['name','file','role','config','note'])<=set(v)
 assert Path(v['file']).name==v['file'] and v['file'].endswith('.py')
 assert v['role'] in ['candidate','control']
 tree=ast.parse(Path('/workspace',v['file']).read_text())
 config=ast.literal_eval(next(x.value for x in tree.body if isinstance(x,ast.Assign) and any(isinstance(t,ast.Name) and t.id=='CONFIG' for t in x.targets)))
 assert v['config']==config==p['source_freeze']['configuration']
 assert hashlib.sha256(Path('/workspace',v['file']).read_bytes()).hexdigest()==p['source_freeze'][v['file']]
# Verify every retrieved industry card is explicitly assessed, without treating search hits as use.
access=[json.loads(x) for x in Path('/workspace/knowledge-access.jsonl').read_text().splitlines() if x]
print('Access events',len(access))
print('PASS strict supplied study schema, evidence/protocol, variant API, source/config hash checks')
print('Model helpers unchanged:',len([x for x in next(c for c in tree.body if isinstance(c,ast.ClassDef) and c.name=='Model').body if isinstance(x,ast.FunctionDef) and x.name not in ['__init__','forward','_task_pool','_task_moment_coefficients']]))
PY
